create table FM_SERVICE_DEFINE (SERVICE_CODE VARCHAR(20) not null  ,MESSAGE_TYPE VARCHAR(10) not null  ,MESSAGE_CODE VARCHAR(10) not null  ,URL VARCHAR(200) null  ,BUSI_CATEGORY VARCHAR(20) null  ,BUSI_SUB_CLASS VARCHAR(10) null  ,BLACKLIST_CHECK_FLAG VARCHAR(1) null  ,WHITE_LIST_CHECK_FLAG VARCHAR(1) null  ,MULTI_CORP_CHECK_FLAG VARCHAR(1) null  ,ACROSS_BRAN_CHECK_FLAG VARCHAR(1) null  ,CLIENT_CHECK_FLAG VARCHAR(1) null  ,ALLOW_REVERSE_FLAG VARCHAR(1) null  ,SERVICE_STATUS VARCHAR(1) null  ,COMPANY VARCHAR(20) null  ,TRAN_TIMESTAMP VARCHAR(26) null  , primary key(SERVICE_CODE,MESSAGE_TYPE,MESSAGE_CODE));